import numpy as np


def min_max_dist_dim2_16() -> np.ndarray:
    """Refine a triangular-lattice seed using deterministic COBYLA packing searches.

    Point zero removes translation, all other coordinates are free, and every
    pair is constrained to have squared distance between a common lower bound
    and one.  Multiple fixed perturbations permit symmetry breaking while the
    normalized triangular lattice remains a dependency-free fallback.
    """
    rt3 = np.sqrt(3.0)
    upper = np.triu_indices(16, 1)

    removed = {(2, 0), (-2, 2), (0, -2)}
    axial = [
        (q, r)
        for q in range(-2, 3)
        for r in range(-2, 3)
        if max(abs(q), abs(r), abs(q + r)) <= 2 and (q, r) not in removed
    ]
    seed = np.array(
        [(q + 0.5 * r, 0.5 * rt3 * r) for q, r in axial],
        dtype=np.float64,
    )
    seed -= seed[0]

    def normalize(points):
        delta = points[:, None, :] - points[None, :, :]
        diameter = np.sqrt(np.max(np.einsum("ijk,ijk->ij", delta, delta)))
        return points / diameter

    def distances2(points):
        delta = points[:, None, :] - points[None, :, :]
        return np.einsum("ijk,ijk->ij", delta, delta)[upper]

    def quality(points):
        d2 = distances2(points)
        return float(np.min(d2) / np.max(d2))

    best = normalize(seed)
    best_quality = quality(best)

    try:
        from scipy.optimize import minimize

        def unpack(v):
            return np.vstack((np.zeros(2), v[:-1].reshape(15, 2)))

        def constraints(v):
            d2 = distances2(unpack(v))
            # The final variable is a distance, rather than a squared
            # distance, which gives COBYLA a better-scaled objective.
            return np.concatenate((d2 - v[-1] * v[-1], 1.0 - d2))

        rng = np.random.default_rng(314159265)
        starts = [best]
        starts.extend(
            normalize(
                np.vstack((
                    np.zeros(2),
                    best[1:] + rng.normal(0.0, scale, size=(15, 2)),
                ))
            )
            for scale in (0.025, 0.050, 0.085)
            for _ in range(3)
        )

        for start in starts:
            # Start strictly below the lattice contact distance so all lower
            # constraints are initially feasible despite roundoff.
            result = minimize(
                lambda v: -v[-1],
                np.r_[start[1:].ravel(), 0.18],
                method="COBYLA",
                constraints={"type": "ineq", "fun": constraints},
                options={
                    "maxiter": 18000,
                    "rhobeg": 0.04,
                    "tol": 2e-10,
                    "catol": 2e-9,
                },
            )
            candidate = normalize(unpack(result.x))
            value = quality(candidate)
            if np.isfinite(value) and value > best_quality:
                best, best_quality = candidate, value
    except Exception:
        pass

    return np.asarray(best, dtype=np.float64)


